List<Map<String,dynamic>> rows(dynamic v)=>v is List?v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():[];
String str(dynamic v,[String fallback=''])=>v==null?fallback:v.toString();
String price(Map<String,dynamic> x){final label=str(x['price_label']);if(label.isNotEmpty)return label;if(x['price']==null)return 'Fərdi təklif';return x['price'].toString()+' '+str(x['currency'],'AZN');}
void openLink(String value)async{final u=Uri.tryParse(value);if(u!=null&&(u.scheme=='https'||u.scheme=='http'))await launchUrl(u,mode:LaunchMode.externalApplication);}
void showError(BuildContext c,Object e)=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(e.toString())));

