class ContactScreen extends StatefulWidget{const ContactScreen({super.key});@override State<ContactScreen> createState()=>_ContactScreenState();}
class _ContactScreenState extends State<ContactScreen>{final form=GlobalKey<FormState>();final name=TextEditingController(),email=TextEditingController(),phone=TextEditingController(),message=TextEditingController();bool busy=false;@override void dispose(){name.dispose();email.dispose();phone.dispose();message.dispose();super.dispose();}
Future<void> send()async{if(!form.currentState!.validate())return;setState(()=>busy=true);try{final result=await ApiService.instance.postInquiry(fullName:name.text.trim(),email:email.text.trim(),phone:phone.text.trim(),message:message.text.trim());if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(str(result['message'],'Müraciət göndərildi.'))));form.currentState!.reset();name.clear();email.clear();phone.clear();message.clear();}catch(e){if(mounted)showError(context,e);}finally{if(mounted)setState(()=>busy=false);}}
