class AssistantScreen extends StatefulWidget{const AssistantScreen({super.key});@override State<AssistantScreen> createState()=>_AssistantScreenState();}
class _AssistantScreenState extends State<AssistantScreen>{final input=TextEditingController();final scroll=ScrollController();final List<Map<String,String>> messages=[{'role':'assistant','content':'Salam! RashadFinance və maliyyə mövzuları haqqında suallarınızı verə bilərsiniz.'}];bool busy=false;@override void dispose(){input.dispose();scroll.dispose();super.dispose();}
Future<void> send()async{final text=input.text.trim();if(text.isEmpty||busy)return;input.clear();setState(()=>messages.add({'role':'user','content':text}));setState(()=>busy=true);try{final history=messages.length>1?messages.sublist(0,messages.length-1).take(8).toList():<Map<String,String>>[];final answer=await ApiService.instance.askAssistant(text,history);if(mounted)setState(()=>messages.add({'role':'assistant','content':answer}));}catch(e){if(mounted)setState(()=>messages.add({'role':'assistant','content':e.toString()}));}finally{if(mounted){setState(()=>busy=false);WidgetsBinding.instance.addPostFrameCallback((_){if(scroll.hasClients)scroll.animateTo(scroll.position.maxScrollExtent,duration:const Duration(milliseconds:250),curve:Curves.easeOut);});}}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('RashadFinance AI')),body:Column(children:[Expanded(child:ListView.builder(controller:scroll,padding:const EdgeInsets.all(16),itemCount:messages.length,itemBuilder:(c,i){final m=messages[i],user=m['role']=='user';return Align(alignment:user?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:BoxConstraints(maxWidth:MediaQuery.of(c).size.width*.82),margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:user?navy:Colors.white,borderRadius:BorderRadius.circular(15)),child:Text(m['content']??'',style:TextStyle(color:user?Colors.white:ink,fontSize:13,height:1.5))));})),if(busy)const Padding(padding:EdgeInsets.all(8),child:LinearProgressIndicator()),SafeArea(top:false,child:Padding(padding:const EdgeInsets.fromLTRB(12,8,12,12),child:Row(children:[Expanded(child:TextField(controller:input,onSubmitted:(_)=>send(),maxLength:1500,decoration:const InputDecoration(counterText:'',hintText:'Sualınızı yazın...'))),const SizedBox(width:8),IconButton.filled(onPressed:busy?null:send,icon:const Icon(Icons.send))])))]));}
